pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        // Ensure the target address has code that will revert on transferFrom
        vm.assume(caddress != address(0) && caddress.code.length > 0);
        // We need to cause the inner call to fail: use a fake token that reverts
        // But since C is fixed, we just test that a failed call causes revert.
        // The simplest: set up a contract that reverts on transferFrom.
        // Deploy a simple revert contract and use it as caddress.
        Reverter r = new Reverter();
        caddress = address(r);
        bool reverted = false;
        try c.transfer(from, caddress, _tos, v) {
            // If no revert, that's the bug
        } catch {
            reverted = true;
        }
        assertTrue(reverted);
    }
}

contract Reverter {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        revert("fail");
    }
}

