pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        // Ensure caddress is a contract that will revert on transferFrom call to trigger the difference
        vm.assume(caddress != address(0));
        vm.assume(caddress != address(c));
        // Deploy a simple contract that always fails on transferFrom
        address failTarget = address(new FailingContract());
        // We'll call transfer with failTarget as the caddress parameter
        // But the test must use caddress from fuzz; we can override by using a cheatcode to set code?
        // Simpler: deploy a contract that reverts at its own address, then call transfer with that address
        // Since we can't modify caddress, we use it as the receiver of funds? No, better: use vm.assume to restrict caddress to the failing contract address.
        // For simplicity, we deploy a failing contract and set caddress to it via assume.
        address failingAddr = address(new FailingContract());
        vm.assume(caddress == failingAddr);
        // Now call transfer – the reference should revert, the buggy should not
        bool reverted = false;
        try c.transfer(from, caddress, _tos, v) {
            // If no revert, we check if it returned false? But interface returns bool and buggy always true.
            // The property: reference always reverts when inner call fails
        } catch {
            reverted = true;
        }
        // The reference contract MUST revert because the inner call to FailingContract's transferFrom will fail
        assertTrue(reverted, "Reference should revert on inner call failure");
    }
}

contract FailingContract {
    // This function selector matches transferFrom(address,address,uint256)
    function transferFrom(address, address, uint256) external pure returns (bool) {
        revert("always fail");
    }
}

